import{_ as a,o,c as t,a0 as r}from"./chunks/framework.jwovEGr5.js";const s=JSON.parse('{"title":"高分子化学-潘祖仁","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/自学视频/高分子化学-潘祖仁.md","filePath":"中山大学/自学视频/高分子化学-潘祖仁.md"}'),i={name:"中山大学/自学视频/高分子化学-潘祖仁.md"};function l(n,e,u,c,p,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="高分子化学-潘祖仁" tabindex="-1">高分子化学-潘祖仁 <a class="header-anchor" href="#高分子化学-潘祖仁" aria-label="Permalink to &quot;高分子化学-潘祖仁&quot;">​</a></h1><h2 id="绪论" tabindex="-1">绪论 <a class="header-anchor" href="#绪论" aria-label="Permalink to &quot;绪论&quot;">​</a></h2><p>Macromolecule（大分子）：包括天然大分子、合成大分子</p><p>高分子化学 → 聚合物化学（PolymerChemistry）</p><p>主要分为两类：聚合物的合成反应、化学反应</p><h3 id="什么是高分子" tabindex="-1">什么是高分子 <a class="header-anchor" href="#什么是高分子" aria-label="Permalink to &quot;什么是高分子&quot;">​</a></h3><p>由原子或原子团（结构单元）以共价键形式连接而成的大分子量同系混合物</p><h3 id="_1-1高分子的基本概念" tabindex="-1">1.1高分子的基本概念 <a class="header-anchor" href="#_1-1高分子的基本概念" aria-label="Permalink to &quot;1.1高分子的基本概念&quot;">​</a></h3><br><h5 id="单体-monomer" tabindex="-1">单体（Monomer） <a class="header-anchor" href="#单体-monomer" aria-label="Permalink to &quot;单体（Monomer）&quot;">​</a></h5><p>合成聚合物的低分子量原料</p><h5 id="重复结构单元-repeatingstructureunit" tabindex="-1">重复结构单元（RepeatingStructureUnit） <a class="header-anchor" href="#重复结构单元-repeatingstructureunit" aria-label="Permalink to &quot;重复结构单元（RepeatingStructureUnit）&quot;">​</a></h5><p>大分子链上化学组成和结构均可重复出现的最小基本单元</p><blockquote><p>重复结构单元（重复单元）和结构单元是不一样的</p></blockquote><h5 id="结构单元-structureunit" tabindex="-1">结构单元（StructureUnit） <a class="header-anchor" href="#结构单元-structureunit" aria-label="Permalink to &quot;结构单元（StructureUnit）&quot;">​</a></h5><p>单体分子通过聚合反应进入大分子链的基本单元。结构单元的匀速组成可以与单体的元素组成相同，也可以不同</p><h5 id="单体单元-monomerunit" tabindex="-1">单体单元（MonomerUnit） <a class="header-anchor" href="#单体单元-monomerunit" aria-label="Permalink to &quot;单体单元（MonomerUnit）&quot;">​</a></h5><p>单体分子通过聚合反应形成的元素组成与单体完全相同的结构单元</p><ul><li>单体单元：原子组成和单体一模一样，只是键发生变化（加聚产物）</li><li>缩聚的结构单元：原子比单体少（脱水/脱HCl），不能叫单体单元</li></ul><h5 id="聚合度-degreeofpolymerization" tabindex="-1">聚合度（DegreeofPolymerization） <a class="header-anchor" href="#聚合度-degreeofpolymerization" aria-label="Permalink to &quot;聚合度（DegreeofPolymerization）&quot;">​</a></h5><p>聚合物分子量大小的一个指标，在聚合物的分子结构式中以<code>n</code>表示，也称为链结数</p><p>有两种表示方法：</p><ol><li>以大分子链中的结构单元数目表示，记为<code>Xn</code>，数均聚合度</li><li>以大分子链中的重复单元数目表示，记为<code>DP</code></li></ol><blockquote><p>Mn = DP × M0</p></blockquote><ul><li>Mn：数均分子量</li><li>DP：聚合度</li><li>M0：重复单元的分子量</li></ul><p>缩聚反应：聚合度受反应程度<code>p</code>控制（Carothers公式）</p><blockquote><p>x = 1/(1-p)</p></blockquote><p>p：反应程度，已经反应的官能团占初始官能团的分数</p><blockquote><p>p = (N0-N)/N0</p></blockquote><p>其中N0是反应起始的官能团数，N是反应进行到某时刻剩余的官能团数</p>',30)])])}const m=a(i,[["render",l]]);export{s as __pageData,m as default};
